    {
      "service": "ts-travel2-service",
      "fault_kind": "http_response_body_corrupted",
      "evidence": [
        {"kind": "trace", "sql": "SELECT 'abn' p, service_name, span_name, attr_span_kind, attr_http_request_method m, attr_http_response_status_code code, count(*) n FROM abnormal_traces WHERE (service_name='ts-basic-service' AND span_name='DELETE /error') OR (service_name='ts-travel2-service' AND attr_span_kind='Client' AND span_name='POST') GROUP BY ALL UNION ALL SELECT 'norm', service_name, span_name, attr_span_kind, attr_http_request_method, attr_http_response_status_code, count(*) FROM normal_traces WHERE (service_name='ts-basic-service' AND span_name='DELETE /error') OR (service_name='ts-travel2-service' AND attr_span_kind='Client' AND span_name='POST') GROUP BY ALL", "claim": "Travel2's outgoing POSTs to basic get 405 on 2712 calls; basic receives them as DELETE /error, whereas normal POSTs return 200."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_http_response_status_code code, count(*) n, quantile_cont(duration,0.95)/1e6 p95_ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY ALL", "claim": "Travel2's trips/left server endpoint returns HTTP 500 on about 2712 requests in the abnormal window."},
        {"kind": "log", "sql": "SELECT service_name, level, substr(message,1,160) msg, count(*) n FROM abnormal_logs WHERE service_name IN ('ts-travel2-service','ts-basic-service') AND level IN ('SEVERE','WARN') GROUP BY ALL ORDER BY n DESC", "claim": "Travel2 logs about 2714 SEVERE dispatcher exceptions; basic logs 2712 WARN 'DELETE not supported' messages."}
      ]
    }
  ],
  "propagation": [
    {"from": "ts-travel2-service", "to": "ts-route-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50, quantile_cont(duration,0.95)/1e6 p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name IN ('ts-route-plan-service') GROUP BY ALL HAVING count(*)>5 ORDER BY service_name, span_name, p", "claim": "Route-plan's cheapestRoute and quickestRoute server spans rise from about 260-320 ms p50 to about 3.9 s p50, with 500s from travel2 failures."}]},
    {"from": "ts-route-plan-service", "to": "ts-travel-plan-service", "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50, quantile_cont(duration,0.95)/1e6 p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name IN ('ts-travel-plan-service') AND span_name='POST' GROUP BY ALL ORDER BY p", "claim": "Travel-plan's client POSTs to route-plan rise to p95 about 60 s in abnormal, from about 430 ms normal."}]},
    {"from": "ts-travel-plan-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50, quantile_cont(duration,0.95)/1e6 p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND span_name LIKE '%travelPlan%' GROUP BY ALL ORDER BY p", "claim": "Dashboard's travelPlan requests to travel-plan rise to p95 about 60 s in the abnormal window."}]},
    {"from": "ts-travel2-service", "to": "ts-ui-dashboard", "evidence": [{"kind": "trace", "sql": "SELECT p, service_name, span_name, attr_span_kind, count(*) n, quantile_cont(duration,0.5)/1e6 p50, quantile_cont(duration,0.95)/1e6 p95 FROM (SELECT 'abn' p, * FROM abnormal_traces UNION ALL SELECT 'norm', * FROM normal_traces) WHERE service_name='ts-ui-dashboard' AND span_name='POST /api/v1/travel2service/trips/left' GROUP BY ALL ORDER BY p", "claim": "Dashboard's trips/left requests to travel2 now take about 3.8 s p50 and fail, versus about 93 ms normal."}]}
  ]
}
